import {randomUUID} from 'node:crypto';
import {Company} from '../../../src/control/company.js';
import {fixture,objective,hire} from '../../helpers.js';
import type {Worker} from '../../../src/domain/model.js';
import {FixtureClock,FixtureSimulator} from '../../../src/control/investment.js';
import {configuration} from '../investment/support.js';
import {SimulatorPublicationSource,type FixturePublicationDescription} from '../../../src/control/publication/simulator-source.js';
import {publicationFixture} from '../publication/support.js';
import type {TeamEnvelope,PaperProposal,PaperReview} from '../../../src/domain/investment-team/types.js';
import type {RuntimeAdapter} from '../../../src/runtime/adapter.js';
import type {Envelope} from '../../../src/domain/publication/types.js';
import {CommittedTeamPublicationSource,type TeamPublicationSelection} from '../../../src/control/publication/team-source.js';
import {hash} from '../../../src/domain/investment/identity.js';
import {MarketStore} from '../../../src/control/market/store.js';
import {MarketFixtureSimulator} from '../../../src/control/market/admission.js';
import {normalizePrice} from '../../../src/domain/market/normalize.js';
import type {CalendarEvidence,InstrumentIdentity} from '../../../src/domain/market/types.js';
export function teamFixture(options:{committed?:boolean}={}){
 const base=fixture();base.company.assignObjective(objective);const setup=base.company.claimNext()!,atlas=setup.worker,scout=base.company.callTool(setup.context,'hire','hire_worker',hire) as Worker;base.company.finish(setup.execution.execution_id,{status:'completed',summary:'Explicit fixture roster, no real employee execution'});
 const p=publicationFixture();const clock=new FixtureClock(new Date().toISOString()),config=configuration({startsAt:clock.now(),calendar:p.config.calendar,authorization:{fixtureOperator:'fixture-owner',authors:[atlas.worker_id],reviewers:[scout.worker_id],expiresAt:'2026-12-01T00:00:00.000Z',maxOrders:100}}),sim=new FixtureSimulator(base.store,clock,'fixture-owner');sim.create(config);
 const market=new MarketStore(base.store),policy=p.policy,calendar=p.market.get<CalendarEvidence>(p.store.get<{id:string}>("SELECT id FROM investment_market_records WHERE kind='calendar'")!.id,'calendar');for(const r of p.store.all<{id:string;kind:'policy'|'calendar'|'instrument';payload:string}>('SELECT * FROM investment_market_records'))market.put(r.id,r.kind,JSON.parse(r.payload),clock.now());const description:FixturePublicationDescription=structuredClone(p.description),publicationEnvelope:Envelope=structuredClone(p.envelope);p.cleanup();description.workers={[atlas.worker_id]:{name:'Fixture coordinator',role:'Fixture role',responsibilities:['Synthetic proposal'],status:'unavailable'},[scout.worker_id]:{name:'Fixture reviewer',role:'Fixture role',responsibilities:['Synthetic review'],status:'unavailable'}};
 const admitted=new MarketFixtureSimulator(market,clock,'fixture-owner');const price=(instrumentId:string,session:string,field:'regular_open'|'regular_close',value:string)=>{const si=calendar.calendar.sessions.find(s=>s.date===session)!,instrument=market.get<InstrumentIdentity>(instrumentId,'instrument'),body=JSON.stringify({schema:'synthetic-price-v1',symbol:instrument.symbols[0]!.symbol,venue:'XNYS',currency:'USD',field,value,adjustment:'raw',session,marketAt:field==='regular_open'?si.open:si.close,availableAt:null,sourceId:`${instrumentId}-${session}-${field}`,sourceVersion:1,status:'verified',correctionOf:null});const evidence=normalizePrice(body,{instrumentId,session,field},policy,instrument,calendar,clock.now(),market.prices());market.put(evidence.id,'price',evidence,clock.now());admitted.observe(config.runId,evidence.id);return evidence;};
 const group=base.company.discussions.create({topic:'Synthetic paper investment exercise',desired_output:'Research, challenge, compare HOLD and permitted paper alternatives',constraints:'Invented market data. No real employee or price claim. No real financial or publication authority.',participant_ids:[atlas.worker_id,scout.worker_id],facilitator_id:atlas.worker_id,synthesizer_id:atlas.worker_id,organize_with_atlas:false,allow_incomplete:true,allow_research:true,receipt_key:randomUUID()});
 const selection:TeamPublicationSelection={groupId:group.group_id,runtimeEvidence:'fake_runtime_fixture',evidenceRights:{}};
 if(options.committed){description.workers[atlas.worker_id]!.responsibilities=['Choose meaningful paper alternatives'];description.workers[scout.worker_id]!.responsibilities=['Challenge the exact proposal and evidence'];}
 const source=options.committed?new CommittedTeamPublicationSource('team-source','Committed fake runtime records',base.store,clock,'fixture-owner',config.runId,description,selection):new SimulatorPublicationSource('team-source','Synthetic runtime fixture',base.store,clock,'fixture-owner',config.runId,description);
 const company=new Company(base.store,base.dir,process.cwd(),'fake',undefined,undefined,{sources:[source],destinations:[{id:'team-destination',title:'No network fixture',origin:'http://127.0.0.1:9999',fixtureLoopback:true,publisherId:'fixture',generation:'1',keyId:'no-key'}],clock});company.mandates.clock={now:()=>Date.parse(clock.now())};
 const bounded:RuntimeAdapter={type:'fake',supportsInterrupt:true,run:base.runtime.run.bind(base.runtime),runBoundedInvestment:base.runtime.run.bind(base.runtime)};company.investmentTeam.runtime=bounded;
 publicationEnvelope.sourceId=source.id;publicationEnvelope.destinationId='team-destination';publicationEnvelope.participants=source.participants;publicationEnvelope.expiresAt='2026-11-01T00:00:00.000Z';publicationEnvelope.futureFinancial=true;if(options.committed)publicationEnvelope.eventTypes.push('discussion.opened','discussion.contribution','discussion.closed');
 const first=company.publication.preview(publicationEnvelope),channelId=first.channelId;

 const envelope:TeamEnvelope={runId:config.runId,groupId:group.group_id,audience:'public_candidate',participants:[{workerId:atlas.worker_id,name:'Fixture coordinator',responsibility:'Choose meaningful paper alternatives'},{workerId:scout.worker_id,name:'Fixture reviewer',responsibility:'Challenge the exact proposal and evidence'}],proposers:[atlas.worker_id],reviewers:[scout.worker_id],submitters:[atlas.worker_id],expiresAt:'2026-11-01T00:00:00.000Z',maxExecutions:24,maxResearch:2,maxProposals:10,maxOrders:10,turnLimits:{inputTokens:8000,outputTokens:1500,maxCostMicros:0},publicationChannelId:channelId};
 const preview=()=>company.investmentTeam.preview(envelope);
 const grant=()=>{const p=preview();company.investmentTeam.consent({scopeId:p.scopeId,digest:p.digest});return p;};
 const control=(action:string)=>company.discussions.control({group_id:group.group_id,action,receipt_key:randomUUID()});
 const claim=()=>{clock.set(new Date(Math.max(Date.now(),Date.parse(clock.now())+1)).toISOString());const c=company.claimWorkNext();if(!c||c.origin!=='conversation')throw new Error('Fixture conversation claim missing');company.conversations.prepareBinding(c.context,company.conversations.binding(c.context)??{worker_id:c.worker.worker_id,runtime_type:'fake',workspace_path:c.worker.workspace_path,runtime_reference:randomUUID(),created_at:clock.now()});company.conversations.activateBinding(c.context);company.conversations.context(c.context);company.recordRuntimeConfig(c.context,{model:'fake-model',reasoning_effort:'none',runtime_version:'fixture-v1',runtime_adapter:'fake',execution_priority:c.execution.execution_priority!});return c;};
 const pair=()=>[claim(),claim()].sort((a,b)=>a.worker.worker_id===atlas.worker_id?-1:b.worker.worker_id===atlas.worker_id?1:0) as [ReturnType<typeof claim>,ReturnType<typeof claim>];
 const call=(c:ReturnType<typeof claim>,name:string,input:unknown,callId=randomUUID())=>{clock.set(new Date(Math.max(Date.now(),Date.parse(clock.now()))).toISOString());return company.conversations.callTool(c.context,callId,name,input) as any;};
 const contribute=(c:ReturnType<typeof claim>,body='Explicit fake-runtime contribution; no real employee behavior claimed',refs:string[]=[])=>call(c,'submit_contribution',{body,contribution_ids:refs,evidence_ids:[],questions:[],answers:[]});
 const finish=(c:ReturnType<typeof claim>)=>company.finish(c.execution.execution_id,{status:'completed',summary:'Fixture turn settled'});
 const approvePublication=()=>{for(const p of base.store.all<PaperProposal>('SELECT * FROM investment_team_proposals')){const r=base.store.get<PaperReview>('SELECT * FROM investment_team_reviews WHERE proposal_id=?',p.proposal_id);if(r){const n=JSON.parse(p.narrative);description.decisions[`${p.decision_id}:${p.revision}`]={mode:'synthetic_fixture_derivative',proposalHash:p.simulator_hash,reviewHash:r.simulator_hash,rationale:n.rationale,alternatives:n.alternatives,risks:n.risks,invalidationCondition:n.invalidationCondition,reviewRationale:r.rationale,dissent:JSON.parse(r.dissent)};}}const p=company.publication.preview(publicationEnvelope);return company.publication.consent({previewId:p.id,digest:p.digest});};
 const evidence=company.discussions.share({group_id:group.group_id,kind:'owner_material',title:'Synthetic research premise',content:'Invented fixture company has uncertain demand; this is not an observed fact. Compare waiting for evidence with a small guarded paper position.',source_id:null,document_path:null,receipt_key:randomUUID(),audience_confirmed:true,audience_scope_version:group.scope_version,audience_worker_ids:[atlas.worker_id,scout.worker_id]});
 selection.evidenceRights[evidence.evidence_id]='owner_authored';
 const proposal={decisionId:'paper-decision',revision:1,action:'HOLD',marketObservationIds:[],order:null,rationale:'Uncertain demand makes waiting a valid option',alternatives:['A small guarded paper position'],risks:['Opportunity cost while waiting'],invalidationCondition:'New verified evidence contradicts the premise',contributionIds:[],evidenceIds:[evidence.evidence_id]};
 return {...base,company,clock,config,sim,source,market,policy,calendar,admitted,price,description,publicationEnvelope,envelope,group,atlas,scout,bounded,channelId,evidence,proposal,preview,grant,control,claim,pair,call,contribute,finish,approvePublication,hash};
}
